from a_common import P,pt,table,svg,txt,line,box

def build(B):
    c='A3.1'
    B.add(c,'sl','Interpreting a binomial name','Two organisms are named *Pan troglodytes* and *Pan paniscus*. What does the shared first word indicate?',correct='They are assigned to the same genus.',wrong=['They must be the same species.','They must have identical genomes.','They must produce fertile hybrids whenever they meet.'],why='The first word is the genus; the second distinguishes species within that genus. The name alone does not establish genomic identity or interbreeding.',statements='A3.1.2-3')
    B.add(c,'sl','Using a biological species concept','Two similar-looking bird populations occupy the same region. Repeated observations show mating between populations and fertile offspring that also reproduce.',[P('Explain how these observations relate to the biological species concept.','Successful interbreeding with fertile offspring supports treating the populations as one biological species.'),P('Explain why appearance alone would be a weaker basis for the same conclusion.','Members of one species can vary in appearance, and distinct species can look similar.')],statements='A3.1.1, A3.1.4')
    B.add(c,'sl','Drawing a species boundary','Constructed crossing data for neighbouring populations show that A×B and B×C produce many fertile offspring, while A×C crosses rarely do so.',[P('Explain why assigning a single species boundary is difficult.','Interbreeding connects A to B and B to C, but the endpoints are more reproductively separated.','Gradual divergence produces an intermediate case rather than a sharp universal boundary.'),P('Suggest one additional observation useful for interpreting the pattern.','Study natural mating/gene flow or offspring fertility across repeated crosses under comparable conditions; credit a relevant observation.')],data=True,statements='A3.1.4-5')
    B.add(c,'sl','Chromosome number and complexity','Humans typically have 46 chromosomes in diploid cells, whereas chimpanzees typically have 48.',[P('Explain why these numbers do not rank the organisms by complexity.','Chromosome count measures how DNA is packaged, not the amount or functional organization of genetic information.'),P('State the expected number in a typical human haploid gamete.','23 chromosomes.'),P('Explain why a diploid chromosome number is usually even.','The cell contains two sets, with homologous chromosomes occurring in pairs.')],statements='A3.1.6')
    karyo=svg(txt(410,30,'Constructed chromosomes from one diploid cell')+''.join(line(x,85,x,85+length,width=12,colour=col)+line(x-15,85+length*.45,x+15,85+length*.45,width=3,colour='#fff')+txt(x,85+length+35,label) for x,length,label,col in [(100,130,'P','#447fa1'),(225,80,'Q','#a67b55'),(350,105,'R','#71956a'),(475,130,'S','#447fa1'),(600,105,'T','#71956a'),(725,80,'U','#a67b55')])+txt(410,330,'Colours summarize matched banding; no replication is represented',15))
    B.add(c,'sl','Matching chromosomes in a karyogram','The constructed schematic shows six unreplicated chromosomes. Matching colour patterns summarize matching banding patterns.',[P('Group the chromosomes into homologous pairs.','P–S, Q–U and R–T.'),P('State two criteria, other than the summary colours, used to match real chromosomes.','Relative chromosome length.','Centromere position or detailed banding pattern; credit either.'),P('Determine the diploid chromosome number in this cell.','$2n=6$.')],diagram=karyo,statements='A3.1.7')
    fusion=svg(txt(410,28,'Constructed alignment of chromosome regions')+line(100,95,360,95,width=16)+line(460,95,720,95,width=16)+txt(230,65,'Ancestral chromosome X')+txt(590,65,'Ancestral chromosome Y')+line(130,225,690,225,width=16)+txt(410,195,'Candidate fused chromosome')+txt(230,130,'A — B — C')+txt(590,130,'D — E — F')+txt(410,265,'A — B — C — D — E — F')+line(365,215,455,215,colour='#b05c35',width=4)+txt(410,310,'Internal telomere-like sequence near the join',16))
    B.add(c,'sl','Testing a chromosome-fusion hypothesis','The constructed alignment models evidence relevant to the proposed origin of human chromosome 2. One chromosome contains regions corresponding to two separate ancestral chromosomes, with telomere-like sequences near the internal join.',[P('Explain how the regional order supports a fusion.','The single chromosome contains the corresponding regions of both ancestral chromosomes in a continuous order.'),P('Explain the significance of internal telomere-like sequence.','Telomeres normally occur at chromosome ends; a remnant at an internal join is consistent with former ends becoming joined.'),P('State one way to strengthen the test.','Compare detailed DNA/banding sequences and centromere remnants across relevant primate chromosomes rather than relying only on the schematic.')],diagram=fusion,statements='A3.1.7')
    B.add(c,'sl','Variation within one species','Two constructed 20-base aligned DNA segments from individuals of one species differ at two positions.',[P('Calculate their percentage sequence identity.',r'$18/20\times100=90\%$.'),P('Explain why sequence differences do not automatically mean different species.','Individuals within a species share most of their genomes but can differ at polymorphic sites.'),P('Explain one limitation of generalizing from this segment to whole-genome similarity.','Twenty bases are a small, possibly unrepresentative sample of the genome.')],data=True,statements='A3.1.8-9')
    B.add(c,'sl','Genome size without a complexity ranking','Constructed database entries give haploid genome sizes for three eukaryotic organisms.'+table(['Organism','Genome / million base pairs','Cell organization'],[['P',3100,'Multicellular animal'],['Q',16000,'Multicellular plant'],['R',45000,'Unicellular protist']]),[P('Calculate the ratio of R’s genome size to P’s, to two significant figures.',r'$45\,000/3100\approx15$.'),P('Evaluate the claim that more DNA always means greater organismal complexity.','The largest genome here belongs to a unicellular organism, so these data do not support a simple universal ranking by genome size.'),P('State one reason genome size and functional complexity need not be proportional.','Genomes can contain differing amounts of non-coding or repetitive DNA; total size does not directly count functional complexity.')],data=True,statements='A3.1.9-10')
    B.add(c,'sl','Changing access to genome sequencing','A constructed cost comparison shows the same type of genome sequencing costing 9000 currency units in one year and 1500 units later.',[P('Calculate the percentage decrease in cost.',pt(r'$\frac{9000-1500}{9000}\times100$.','M1'),r'Approximately $83.3\%$.'),P('Explain one research benefit of lower cost.','More organisms or individuals can be sequenced for a fixed budget, improving comparisons of variation or evolutionary relationships.'),P('Explain why lower cost alone does not guarantee clinically useful predictions.','Interpretation also requires reliable links between variants, environment and outcomes; sequence alone is insufficient.')],data=True,statements='A3.1.11')
    B.add(c,'sl','Within-species and between-species comparisons','For a constructed aligned gene region, two individuals of species X differ at 3 sites out of 600; an individual of X and one of Y differ at 42 sites.',[P('Calculate the percentage differences for the two comparisons.',r'Within X: $3/600\times100=0.50\%$.',r'Between X and Y: $42/600\times100=7.0\%$.'),P('Explain the conclusion that is supported, and its limit.','For this sampled region, between-species variation is greater; one region and few individuals cannot establish the relationship for every gene or species.')],data=True,statements='A3.1.8-9')
    B.add(c,'sl','Defining the genome','A researcher sequences all hereditary DNA from an organism, including sequences that do not code for proteins. Which description is most accurate?',correct='The genome includes the organism’s complete genetic information, including non-protein-coding sequences.',wrong=['The genome includes only genes being expressed at that moment.','The genome is the set of all proteins currently present.','The genome excludes every sequence that does not code for an enzyme.'],why='A genome concerns the full hereditary information, not only active genes or protein products.',statements='A3.1.8')
    B.add(c,'ahl','Species in an asexual lineage','A microbial lineage reproduces without mating. A researcher tries to decide its species membership solely by testing whether two individuals produce fertile offspring together.',[P('Explain why this test is unsuitable.','The fertile-interbreeding criterion assumes sexual reproduction, which does not occur in this lineage.'),P('Suggest a useful alternative type of evidence.','Compare genetic sequences and consistent ecological or structural traits to identify coherent groups.'),P('Explain why an alternative method may still involve judgement.','Different thresholds or selected traits can divide a continuous range of variation in different ways.')],statements='A3.1.12')
    B.add(c,'ahl','Horizontal transfer and bacterial classification','Constructed sequence evidence suggests that bacterial strain X shares most genes with lineage P but recently acquired one resistance gene from lineage Q.',[P('Explain why the transferred gene can mislead a classification based on that gene alone.','Its history follows horizontal transfer from Q rather than only the ancestry of the rest of strain X.'),P('Suggest a stronger comparison.','Use many conserved genes or genome-wide evidence and consider gene transfer when inferring relationships.')],data=True,statements='A3.1.12')
    B.add(c,'ahl','Chromosomes in an interspecific hybrid','In a constructed plant example, species X has 12 chromosomes in a haploid gamete and species Y has 15. The gametes fuse to form a hybrid.',[P('Calculate the hybrid’s chromosome number.','$12+15=27$ chromosomes.'),P('Explain why fertility may be reduced.','Chromosomes from the two species may lack suitable homologous partners during meiosis.','Irregular pairing and segregation can produce gametes with unbalanced chromosome complements.'),P('Explain why the count alone does not prove complete sterility.','Fertility also depends on chromosome homology, pairing behaviour and reproductive mechanisms; it must be tested.')],data=True,statements='A3.1.13')
    B.add(c,'ahl','Designing a dichotomous key','Four constructed plant specimens have the following traits.'+table(['Specimen','Leaves','Leaf arrangement'],[['P','simple','opposite'],['Q','simple','alternate'],['R','compound','opposite'],['S','compound','alternate']]),[P('Write a first pair of contrasting statements that divides the four specimens into two groups.','1a Leaves simple: go to step2; 1b leaves compound: go to step3.'),P('Complete the key so every specimen can be identified.','Step2: opposite=P, alternate=Q.','Step3: opposite=R, alternate=S.'),P('Explain why an imprecise split such as “large leaves” versus “small leaves” may be less useful.','Without a measurable threshold the categories can overlap or depend on observer judgement.')],data=True,statements='A3.1.14')
    B.add(c,'ahl','Interpreting environmental DNA','A constructed survey detects a fish DNA barcode in three water samples downstream of a lake but not in laboratory blanks.',[P('Explain what conclusion is supported.','DNA matching the fish is present in those samples, supporting its recent presence in the contributing environment.'),P('Explain why this does not establish the number of living fish at each sampling point.','DNA can persist or be transported, and shedding/detection rates vary; barcode detection is not a direct count of living fish.'),P('Explain the role of the blanks.','They test for contamination introduced during sampling or laboratory processing.')],data=True,statements='A3.1.15')

    c='A3.2'
    B.add(c,'ahl','Why classify organisms','A researcher discovers an unfamiliar organism and assigns it to a well-supported evolutionary group.',[P('Explain two practical benefits of doing so.','Classification organizes and communicates information about biological diversity.','Shared ancestry allows testable predictions about features the organism may share with other members.')],statements='A3.2.1, A3.2.3')
    B.add(c,'ahl','Ranks versus evolutionary history','Two traditional families contain very different depths of evolutionary divergence. Which statement best explains why their equal rank is not an exact measure of relatedness?',correct='Taxonomic ranks are assigned categories and need not represent equal divergence times.',wrong=['All families must have exactly the same number of species.','Every family originated at the same date.','Naming a group prevents future evolutionary change.'],why='Rank is not a calibrated time scale; clade relationships are inferred from ancestry and evidence rather than equal labels alone.',statements='A3.2.2')
    tree=svg(txt(410,30,'Constructed cladogram; branch lengths are not a time scale')+line(90,185,220,185)+line(220,80,220,290)+line(220,80,700,80)+line(220,290,370,290)+line(370,200,370,290)+line(370,200,700,200)+line(370,290,520,290)+line(520,260,520,330)+line(520,260,700,260)+line(520,330,700,330)+txt(740,86,'W')+txt(740,206,'X')+txt(740,266,'Y')+txt(740,336,'Z')+txt(90,170,'root',14)+txt(370,315,'N1',15)+txt(520,245,'N2',15),820,385)
    B.add(c,'ahl','Reading common ancestry','Use the constructed cladogram.',[P('Identify the pair with the most recent common ancestor.','Y and Z.'),P('State all terminal groups descended from node N1.','X, Y and Z.'),P('Explain why W should not be described as the ancestor of the other present-day groups.','W is a terminal group; the common ancestor is represented by an earlier internal node, not by a present-day tip.')],diagram=tree,statements='A3.2.4, A3.2.7')
    B.add(c,'ahl','Recognizing a complete clade','In a rooted tree, a node has three descendant lineages P, Q and R. A proposed group contains P and Q but excludes R.',[P('Explain why this group is not a complete clade rooted at that node.','A clade contains the common ancestor and all its descendants, so R must also be included.'),P('Explain one advantage of using complete clades in classification.','Membership consistently represents common ancestry rather than an arbitrary selection of descendants.')],statements='A3.2.3-4')
    B.add(c,'ahl','Comparing aligned sequences','A constructed alignment of the same homologous DNA region is shown.'+table(['Taxon','Sequence'],[['P','A C G T A A'],['Q','A C G T G A'],['R','T T G C G C']]),[P('Count the differences between P and Q, and between P and R.','P–Q: 1 difference; P–R: 5 differences.'),P('Suggest the closest pair on this evidence.','P and Q have the greatest sequence similarity.'),P('Explain why more sequence data would strengthen the inference.','A short region may be unrepresentative or affected by chance similarity, selection or differing rates; independent regions provide a broader test.')],data=True,statements='A3.2.4, A3.2.6')
    B.add(c,'ahl','A calibrated molecular clock','For a constructed example, two lineages accumulate differences in a chosen region at a combined rate of 3 substitutions per million years. They differ by 18 substitutions. Assume the stated combined rate is constant.',[P('Estimate the time since divergence.',pt('$18/3$.','M1'),'6 million years.'),P('Explain why the result is an estimate rather than an exact date.','Mutation/substitution rates can vary with generation time, selection and other factors, so the constant-rate model is approximate.')],data=True,statements='A3.2.5')
    B.add(c,'ahl','Avoiding a two-lineage clock error','A constructed molecular clock gives 2 substitutions per million years **per lineage** after divergence. Two sequences differ by 20 substitutions, with no reversals or repeated changes assumed.',[P('Calculate the divergence time.','Both lineages contribute, so $t=20/(2+2)=5$ million years.'),P('Explain the error in dividing 20 by 2.','It assigns all observed differences to one lineage and ignores changes accumulated on the other branch.')],data=True,statements='A3.2.5')
    B.add(c,'ahl','Choosing the most parsimonious model','Two candidate cladograms explain a constructed character matrix. Tree U requires six changes and tree V requires nine changes under the same character model.',[P('Identify the tree preferred by parsimony and explain why.','Tree U is preferred because it accounts for the observations with fewer changes.'),P('Explain why parsimony does not guarantee the true historical tree.','Real evolution can involve repeated changes, reversals or unequal rates; a simpler explanation may not match every historical event.')],data=True,statements='A3.2.6')
    B.add(c,'ahl','Rotating a branch at a node','A cladogram is redrawn by exchanging the left-to-right positions of two sister groups without changing any connections. Which conclusion is correct?',correct='The evolutionary relationships are unchanged.',wrong=['The older group has become the younger group.','The common ancestor has disappeared.','The group drawn farther right is now more evolved.'],why='Relationships depend on branching connections and common ancestors, not the arbitrary spatial order of tips.',statements='A3.2.7')
    B.add(c,'ahl','A morphology-based grouping is challenged','Two constructed plant groups share a similar floral shape. Analysis of several independent DNA regions places each closer to a different group than to the other.',[P('Suggest a biological explanation for the morphological similarity.','Similar selection pressures may have produced convergent features independently.'),P('Explain why the sequence evidence can support revising the classification.','Concordant evidence from several genes may better reveal ancestry than a single potentially analogous trait.'),P('State one reason to inspect the molecular methods before revising the classification.','Errors in alignment, sampling, gene identification or tree inference could produce misleading relationships; credit a relevant concern.')],data=True,statements='A3.2.8')
    B.add(c,'ahl','Why compare ribosomal RNA','A classification study compares homologous ribosomal RNA sequences from a wide range of organisms.',[P('Explain one advantage of this evidence.','Ribosomal RNA occurs across cellular life and contains homologous sequences that can be compared across distant groups.'),P('Name the three domains recognized by the resulting broad classification.','Bacteria, Archaea and Eukarya (or Eukaryota).'),P('Explain why the lack of a nucleus does not place all organisms in one of these domains.','Both bacteria and archaea lack nuclei but differ in molecular characteristics and ancestry.')],statements='A3.2.9')
    B.add(c,'ahl','Interpreting an internal node','A diagram labels an internal branch point N. What does N normally represent in a cladogram?',correct='A hypothetical common ancestor of the descendant branches.',wrong=['A living species that must still exist unchanged.','A mutation that necessarily occurred in every gene at once.','A measured extinction date even when no time scale is provided.'],why='The node represents inferred common ancestry. Its exact date or phenotype requires additional evidence.',statements='A3.2.7')
    B.add(c,'ahl','A clock affected by generation time','Two constructed lineages diverged at the same time from a common ancestor. One has accumulated more substitutions in a neutral region. A candidate explanation is a higher number of generations per unit time.',[P('Explain why this could affect a molecular-clock estimate.','More generations can create more copying opportunities per unit time, changing the apparent substitution rate.'),P('Explain why applying one rate indiscriminately could be misleading.','A faster-evolving lineage may appear older if its extra differences are interpreted solely as extra elapsed time.'),P('Suggest one improvement.','Calibrate rates with independent dated events and allow different rates for different lineages.')],data=True,statements='A3.2.5')
    B.add(c,'ahl','Selecting homologous evidence','A researcher compares a digestive enzyme in one species with an unrelated structural protein in another and uses the number of amino acid differences to estimate relatedness.',[P('Explain the central problem.','The proteins are not established homologous versions of the same ancestral sequence, so aligned differences do not measure divergence from a shared sequence in the intended way.'),P('Suggest a valid replacement comparison.','Compare homologous genes or proteins across the taxa, using aligned corresponding positions and sufficient sequence length.')],statements='A3.2.4, A3.2.6')
    B.add(c,'ahl','Conflicting gene trees','In a constructed study, one gene supports tree P and another supports tree Q. Each tree fits its own data strongly.',[P('Explain why the conflict should not simply be hidden.','Different genes can have different histories or methodological biases; the conflict is relevant uncertainty in the inference.'),P('Suggest two ways to investigate it.','Compare additional independent genes or genome-wide data.','Check alignment, sampling and the possibility of gene transfer or other processes that make gene history differ from species history.')],data=True,statements='A3.2.6, A3.2.8')
    B.add(c,'ahl','Using an evolutionary classification to predict a trait','A newly sampled species is placed within a well-supported clade whose other sampled members all have a particular enzyme.',[P('State a reasonable prediction.','The new species may also possess the enzyme or its homologous gene.'),P('Explain why the prediction remains testable rather than certain.','The lineage could have lost or modified the trait; direct genetic or biochemical evidence is needed.'),P('Describe an observation that would challenge the prediction.','Reliable evidence that the gene and enzyme activity are absent despite adequate detection controls would challenge it.')],statements='A3.2.3-4')
